/**
 * @file aisoc_dds_participant.cpp
 * @brief Fast DDS DomainParticipant management and profile loading
 * Task ID: TWIN-05
 * Owner: ENG-DDS
 */

#include "aisoc_dds_internal.hpp"

#include <fastdds/dds/domain/DomainParticipantFactory.hpp>
#include <fastdds/dds/domain/qos/DomainParticipantQos.hpp>

static void register_types(
    eprosima::fastdds::dds::DomainParticipant* part
) {
    eprosima::fastdds::dds::TypeSupport type_raw(new aisoc::dds::RawTempPubSubType());
    type_raw.register_type(part);

    eprosima::fastdds::dds::TypeSupport type_snap(new aisoc::dds::TempSnapshotPubSubType());
    type_snap.register_type(part);

    eprosima::fastdds::dds::TypeSupport type_motion(new aisoc::dds::MotionStatusPubSubType());
    type_motion.register_type(part);

    eprosima::fastdds::dds::TypeSupport type_filament(new aisoc::dds::FilamentStatusPubSubType());
    type_filament.register_type(part);
}

aisoc_dds_status_t aisoc_dds_load_profiles(
    const char *xml_path
) {
    if (xml_path == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }
    auto factory = eprosima::fastdds::dds::DomainParticipantFactory::get_instance();
    if (factory == nullptr) {
        return AISOC_DDS_ERR_INIT_FAILED;
    }
    const eprosima::fastdds::dds::ReturnCode_t ret = factory->load_XML_profiles_file(xml_path);
    if (ret != eprosima::fastdds::dds::RETCODE_OK) {
        return AISOC_DDS_ERR_INIT_FAILED;
    }
    return AISOC_DDS_OK;
}

static aisoc_dds_status_t init_participant_entities(
    aisoc_dds_participant_t* part_obj,
    eprosima::fastdds::dds::DomainParticipant* dds_part
) {
    eprosima::fastdds::dds::Publisher* pub = dds_part->create_publisher(
        eprosima::fastdds::dds::PUBLISHER_QOS_DEFAULT
    );
    if (pub == nullptr) {
        return AISOC_DDS_ERR_INIT_FAILED;
    }

    eprosima::fastdds::dds::Subscriber* sub = dds_part->create_subscriber(
        eprosima::fastdds::dds::SUBSCRIBER_QOS_DEFAULT
    );
    if (sub == nullptr) {
        dds_part->delete_publisher(pub);
        return AISOC_DDS_ERR_INIT_FAILED;
    }

    part_obj->dds_participant = dds_part;
    part_obj->dds_publisher = pub;
    part_obj->dds_subscriber = sub;
    return AISOC_DDS_OK;
}

aisoc_dds_status_t aisoc_dds_participant_create(
    const aisoc_dds_participant_config_t *config,
    aisoc_dds_participant_t **out_part
) {
    if (out_part == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }
    *out_part = nullptr;

    if (aisoc::dds::g_participant_count.load() >= AISOC_DDS_MAX_PARTICIPANTS) {
        return AISOC_DDS_ERR_RESOURCE_LIMIT;
    }

    auto factory = eprosima::fastdds::dds::DomainParticipantFactory::get_instance();
    if (factory == nullptr) {
        return AISOC_DDS_ERR_INIT_FAILED;
    }

    if (config != nullptr && config->profile_xml_path != nullptr) {
        factory->load_XML_profiles_file(config->profile_xml_path);
    }

    const uint32_t domain_id = (config != nullptr) ? config->domain_id : 0U;
    eprosima::fastdds::dds::DomainParticipantQos part_qos =
        eprosima::fastdds::dds::PARTICIPANT_QOS_DEFAULT;
    if (config != nullptr && config->participant_name != nullptr) {
        part_qos.name(config->participant_name);
    }

    eprosima::fastdds::dds::DomainParticipant* dds_part =
        factory->create_participant(domain_id, part_qos);
    if (dds_part == nullptr) {
        return AISOC_DDS_ERR_INIT_FAILED;
    }

    register_types(dds_part);

    aisoc_dds_participant_t* part_obj = new aisoc_dds_participant();
    const aisoc_dds_status_t status = init_participant_entities(part_obj, dds_part);
    if (status != AISOC_DDS_OK) {
        factory->delete_participant(dds_part);
        delete part_obj;
        return status;
    }

    aisoc::dds::g_participant_count.fetch_add(1U);
    *out_part = part_obj;
    return AISOC_DDS_OK;
}

aisoc_dds_status_t aisoc_dds_participant_destroy(
    aisoc_dds_participant_t *part
) {
    if (part == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }

    std::lock_guard<std::mutex> lock(part->mutex);
    if (part->dds_participant != nullptr) {
        part->dds_participant->delete_contained_entities();
        auto factory = eprosima::fastdds::dds::DomainParticipantFactory::get_instance();
        if (factory != nullptr) {
            factory->delete_participant(part->dds_participant);
        }
        part->dds_participant = nullptr;
    }
    part->dds_publisher = nullptr;
    part->dds_subscriber = nullptr;

    aisoc::dds::g_participant_count.fetch_sub(1U);
    delete part;
    return AISOC_DDS_OK;
}
