#include "aisoc_dds_internal.hpp"
#include <chrono>

static eprosima::fastdds::dds::Topic* resolve_topic(
    eprosima::fastdds::dds::DomainParticipant* dds_part,
    const char* topic_name
) {
    const char* type_name = aisoc::dds::get_type_name_for_topic(topic_name);
    if (type_name == nullptr) {
        return nullptr;
    }
    const eprosima::fastdds::dds::Duration_t zero_wait{0, 0};
    eprosima::fastdds::dds::Topic* existing = dds_part->find_topic(topic_name, zero_wait);
    if (existing != nullptr) {
        return existing;
    }
    eprosima::fastdds::dds::TopicQos topic_qos = eprosima::fastdds::dds::TOPIC_QOS_DEFAULT;
    return dds_part->create_topic(topic_name, type_name, topic_qos);
}

aisoc_dds_status_t aisoc_dds_publisher_create(
    aisoc_dds_participant_t *part,
    const aisoc_dds_publisher_config_t *config,
    aisoc_dds_publisher_t **out_pub
) {
    if (part == nullptr || config == nullptr || out_pub == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }
    if (config->topic_name == nullptr) {
        return AISOC_DDS_ERR_INVALID_PARAM;
    }
    *out_pub = nullptr;

    if (aisoc::dds::g_publisher_count.load() >= AISOC_DDS_MAX_PUBLISHERS) {
        return AISOC_DDS_ERR_RESOURCE_LIMIT;
    }

    std::lock_guard<std::mutex> lock(part->mutex);
    eprosima::fastdds::dds::Topic* topic = resolve_topic(part->dds_participant, config->topic_name);
    if (topic == nullptr) {
        return AISOC_DDS_ERR_PUB_FAILED;
    }

    aisoc_dds_publisher_t* pub = new aisoc_dds_publisher();
    pub->parent = part;
    pub->dds_topic = topic;
    pub->topic_name = config->topic_name;
    pub->matched_count.store(0U);
    pub->listener = new aisoc::dds::AisocWriterListener(pub);

    eprosima::fastdds::dds::DataWriterQos w_qos = eprosima::fastdds::dds::DATAWRITER_QOS_DEFAULT;
    aisoc::dds::configure_writer_qos(config->topic_name, config->qos_profile, w_qos);

    pub->dds_writer = part->dds_publisher->create_datawriter(
        topic, w_qos, pub->listener, eprosima::fastdds::dds::StatusMask::all()
    );
    if (pub->dds_writer == nullptr) {
        part->dds_participant->delete_topic(topic);
        delete pub->listener;
        delete pub;
        return AISOC_DDS_ERR_PUB_FAILED;
    }

    aisoc::dds::g_publisher_count.fetch_add(1U);
    *out_pub = pub;
    return AISOC_DDS_OK;
}

aisoc_dds_status_t aisoc_dds_publisher_destroy(
    aisoc_dds_publisher_t *pub
) {
    if (pub == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }
    if (pub->parent != nullptr && pub->parent->dds_publisher != nullptr) {
        std::lock_guard<std::mutex> lock(pub->parent->mutex);
        if (pub->dds_writer != nullptr) {
            pub->parent->dds_publisher->delete_datawriter(pub->dds_writer);
            pub->dds_writer = nullptr;
        }
        if (pub->parent->dds_participant != nullptr && pub->dds_topic != nullptr) {
            pub->parent->dds_participant->delete_topic(pub->dds_topic);
            pub->dds_topic = nullptr;
        }
    }
    if (pub->listener != nullptr) {
        delete pub->listener;
        pub->listener = nullptr;
    }
    aisoc::dds::g_publisher_count.fetch_sub(1U);
    delete pub;
    return AISOC_DDS_OK;
}

