aisoc_dds_status_t aisoc_dds_publisher_wait_for_matched(
    aisoc_dds_publisher_t *pub,
    uint32_t min_matches,
    uint32_t timeout_ms
) {
    if (pub == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
