        aisoc_dds_status_t st = aisoc_dds_publisher_create(part, &pub_cfg, &pubs[i]);
        assert(st == AISOC_DDS_OK);
        assert(pubs[i] != nullptr);
    }

    aisoc_dds_publisher_t* overflow_pub = nullptr;
    aisoc_dds_status_t st_overflow = aisoc_dds_publisher_create(part, &pub_cfg, &overflow_pub);
    assert(st_overflow == AISOC_DDS_ERR_RESOURCE_LIMIT);
    assert(overflow_pub == nullptr);

    aisoc_dds_publisher_destroy(pubs[0]);
    pubs[0] = nullptr;
    aisoc_dds_status_t st_retry = aisoc_dds_publisher_create(part, &pub_cfg, &pubs[0]);
    assert(st_retry == AISOC_DDS_OK);
    assert(pubs[0] != nullptr);

    for (uint32_t i = 0; i < AISOC_DDS_MAX_PUBLISHERS; ++i) {
        if (pubs[i] != nullptr) {
            aisoc_dds_publisher_destroy(pubs[i]);
            pubs[i] = nullptr;
        }
    }
    std::cout << ">>> Entity Quota Hard Limits: 100% PASSED" << std::endl;
}

