const char* get_type_name_for_topic(const char* topic_name) {
    if (topic_name == nullptr) {
        return nullptr;
    }
    if (std::strcmp(topic_name, AISOC_TOPIC_RAW_TEMP) == 0) {
        return AISOC_TYPE_RAW_TEMP;
    }
    if (std::strcmp(topic_name, AISOC_TOPIC_TEMP_SNAPSHOT) == 0) {
        return AISOC_TYPE_TEMP_SNAPSHOT;
    }
    if (std::strcmp(topic_name, AISOC_TOPIC_MOTION_STATUS) == 0) {
        return AISOC_TYPE_MOTION_STATUS;
    }
    if (std::strcmp(topic_name, AISOC_TOPIC_FILAMENT_STATUS) == 0) {
        return AISOC_TYPE_FILAMENT_STATUS;
    }
    return nullptr;
}

static uint32_t get_history_depth(const char* topic_name) {
    const bool is_snapshot = (topic_name != nullptr && std::strcmp(topic_name, AISOC_TOPIC_TEMP_SNAPSHOT) == 0);
    return is_snapshot ? 1U : 5U;
}

static uint32_t get_max_samples(const char* topic_name) {
    const bool is_snapshot = (topic_name != nullptr && std::strcmp(topic_name, AISOC_TOPIC_TEMP_SNAPSHOT) == 0);
    return is_snapshot ? 10U : 50U;
}

void configure_writer_qos(
    const char* topic_name,
    aisoc_dds_qos_profile_t profile,
    eprosima::fastdds::dds::DataWriterQos& qos
) {
    const uint32_t depth = get_history_depth(topic_name);
    const uint32_t max_samples = get_max_samples(topic_name);

    qos.history().kind = eprosima::fastdds::dds::KEEP_LAST_HISTORY_QOS;
    qos.history().depth = static_cast<int32_t>(depth);
    qos.resource_limits().max_samples = static_cast<int32_t>(max_samples);
    qos.resource_limits().max_instances = 1;
    qos.resource_limits().max_samples_per_instance = static_cast<int32_t>(max_samples);

    if (profile == AISOC_DDS_QOS_RELIABLE_VOLATILE) {
        qos.reliability().kind = eprosima::fastdds::dds::RELIABLE_RELIABILITY_QOS;
        qos.durability().kind = eprosima::fastdds::dds::VOLATILE_DURABILITY_QOS;
    } else if (profile == AISOC_DDS_QOS_BEST_EFFORT_TRANSIENT_LOCAL) {
        qos.reliability().kind = eprosima::fastdds::dds::BEST_EFFORT_RELIABILITY_QOS;
        qos.durability().kind = eprosima::fastdds::dds::TRANSIENT_LOCAL_DURABILITY_QOS;
    } else {
        qos.reliability().kind = eprosima::fastdds::dds::RELIABLE_RELIABILITY_QOS;
        qos.durability().kind = eprosima::fastdds::dds::TRANSIENT_LOCAL_DURABILITY_QOS;
    }
}

