void AisocWriterListener::on_publication_matched(
    eprosima::fastdds::dds::DataWriter* writer,
    const eprosima::fastdds::dds::PublicationMatchedStatus& info
) {
    static_cast<void>(writer);
    if (pub_ == nullptr) {
        return;
    }
    const uint32_t count = static_cast<uint32_t>(info.current_count);
    pub_->matched_count.store(count);
    pub_->cv_matched.notify_all();
}

void AisocReaderListener::on_subscription_matched(
    eprosima::fastdds::dds::DataReader* reader,
    const eprosima::fastdds::dds::SubscriptionMatchedStatus& info
) {
    static_cast<void>(reader);
    if (sub_ == nullptr) {
        return;
    }
    const uint32_t count = static_cast<uint32_t>(info.current_count);
    sub_->matched_count.store(count);
    sub_->cv_matched.notify_all();
}

static void dispatch_raw_temp(
    aisoc_dds_subscriber* sub,
    eprosima::fastdds::dds::DataReader* reader
) {
    aisoc_raw_temp_t sample;
    eprosima::fastdds::dds::SampleInfo info;
    while (reader->take_next_sample(&sample, &info) == eprosima::fastdds::dds::RETCODE_OK) {
        const bool is_valid = (info.valid_data != 0);
        if (is_valid && sub->config.on_raw_temp != nullptr) {
            sub->config.on_raw_temp(&sample, sub->config.user_data);
        }
    }
}

static void dispatch_temp_snapshot(
    aisoc_dds_subscriber* sub,
    eprosima::fastdds::dds::DataReader* reader
) {
    aisoc_temp_snapshot_t sample;
    eprosima::fastdds::dds::SampleInfo info;
    while (reader->take_next_sample(&sample, &info) == eprosima::fastdds::dds::RETCODE_OK) {
        const bool is_valid = (info.valid_data != 0);
        if (is_valid && sub->config.on_temp_snapshot != nullptr) {
            sub->config.on_temp_snapshot(&sample, sub->config.user_data);
        }
    }
}

void AisocReaderListener::on_data_available(
    eprosima::fastdds::dds::DataReader* reader
) {
    if (sub_ == nullptr || reader == nullptr) {
        return;
    }
    const bool is_raw_temp = (sub_->topic_name == AISOC_TOPIC_RAW_TEMP);
    const bool is_snapshot = (sub_->topic_name == AISOC_TOPIC_TEMP_SNAPSHOT);
    if (is_raw_temp && sub_->config.on_raw_temp != nullptr) {
        dispatch_raw_temp(sub_, reader);
    } else if (is_snapshot && sub_->config.on_temp_snapshot != nullptr) {
        dispatch_temp_snapshot(sub_, reader);
    }
    sub_->cv_data.notify_all();
}

