static void test_history_keep_last_5(aisoc_dds_participant_t* part) {
    std::cout << "[Test 5] Testing History Depth KEEP_LAST(5)..." << std::endl;
    aisoc_dds_publisher_config_t pub_cfg = {AISOC_TOPIC_RAW_TEMP, AISOC_DDS_QOS_RELIABLE_TRANSIENT_LOCAL};
    aisoc_dds_publisher_t* pub = nullptr;
    assert(aisoc_dds_publisher_create(part, &pub_cfg, &pub) == AISOC_DDS_OK);

    publish_sequence_samples(pub, 10U);
    std::cout << "Published 10 samples (seq 1..10) into KEEP_LAST(5) history" << std::endl;

    std::this_thread::sleep_for(std::chrono::milliseconds(200));

    aisoc_dds_subscriber_config_t sub_cfg = {};
    sub_cfg.topic_name = AISOC_TOPIC_RAW_TEMP;
    sub_cfg.qos_profile = AISOC_DDS_QOS_RELIABLE_TRANSIENT_LOCAL;
    aisoc_dds_subscriber_t* sub = nullptr;
    assert(aisoc_dds_subscriber_create(part, &sub_cfg, &sub) == AISOC_DDS_OK);

    std::vector<uint32_t> rx_ids;
    const uint32_t total = collect_samples(sub, rx_ids);
    std::cout << "Late subscriber collected " << total << " samples: ";
    for (uint32_t id : rx_ids) std::cout << id << " ";
    std::cout << std::endl;

    assert(total == 5U);
    assert(rx_ids[0] == 6U);
    assert(rx_ids[4] == 10U);

    aisoc_dds_publisher_destroy(pub);
    aisoc_dds_subscriber_destroy(sub);
    std::cout << ">>> History Depth KEEP_LAST(5) Test: 100% PASSED" << std::endl;
}

