static int run_cross_process_child_sub(void) {
    aisoc_dds_participant_config_t part_cfg = {0, "child_sub_participant", nullptr};
    aisoc_dds_participant_t* part = nullptr;
    if (aisoc_dds_participant_create(&part_cfg, &part) != AISOC_DDS_OK) {
        return 1;
    }

    aisoc_dds_subscriber_config_t sub_cfg = {};
    sub_cfg.topic_name = AISOC_TOPIC_RAW_TEMP;
    sub_cfg.qos_profile = AISOC_DDS_QOS_RELIABLE_VOLATILE;
    aisoc_dds_subscriber_t* sub = nullptr;
    if (aisoc_dds_subscriber_create(part, &sub_cfg, &sub) != AISOC_DDS_OK) {
        aisoc_dds_participant_destroy(part);
        return 2;
    }

    aisoc_raw_temp_t rx_sample = {};
    const aisoc_dds_status_t st = aisoc_dds_wait_for_raw_temp(sub, 5000U, &rx_sample);
    const bool valid = (st == AISOC_DDS_OK && rx_sample.sequence_id == 8888U);

    aisoc_dds_subscriber_destroy(sub);
    aisoc_dds_participant_destroy(part);
    return valid ? 0 : 3;
}

static int run_cross_process_parent_pub(pid_t child_pid) {
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
    aisoc_dds_participant_config_t part_cfg = {0, "parent_pub_participant", nullptr};
    aisoc_dds_participant_t* part = nullptr;
    assert(aisoc_dds_participant_create(&part_cfg, &part) == AISOC_DDS_OK);

    aisoc_dds_publisher_config_t pub_cfg = {AISOC_TOPIC_RAW_TEMP, AISOC_DDS_QOS_RELIABLE_VOLATILE};
    aisoc_dds_publisher_t* pub = nullptr;
    assert(aisoc_dds_publisher_create(part, &pub_cfg, &pub) == AISOC_DDS_OK);

    assert(aisoc_dds_publisher_wait_for_matched(pub, 1U, 4000U) == AISOC_DDS_OK);

    aisoc_raw_temp_t tx_sample;
    init_sample_raw_temp(&tx_sample, 8888U);
    assert(aisoc_dds_publish_raw_temp(pub, &tx_sample) == AISOC_DDS_OK);

    int status = 0;
    waitpid(child_pid, &status, 0);
    const int exit_code = WEXITSTATUS(status);

    aisoc_dds_publisher_destroy(pub);
    aisoc_dds_participant_destroy(part);
    return exit_code;
}

static void test_cross_process_ipc(const char* exec_path) {
    std::cout << "[Test 6] Testing Real Cross-Process IPC with fork + exec..." << std::endl;
    const pid_t pid = fork();
    if (pid == 0) {
        char* args[] = {const_cast<char*>(exec_path), const_cast<char*>("--child-sub"), nullptr};
        execv(exec_path, args);
        _exit(127);
    } else if (pid > 0) {
        const int exit_code = run_cross_process_parent_pub(pid);
        assert(exit_code == 0);
        std::cout << ">>> Cross-Process IPC Test: 100% PASSED (child exit=0)" << std::endl;
    } else {
        std::cerr << "Fork failed!" << std::endl;
        assert(false);
    }
}

