RawTempPubSubType::RawTempPubSubType() {
    set_name(AISOC_TYPE_RAW_TEMP);
    max_serialized_type_size = 40U;
    is_compute_key_provided = false;
}

bool RawTempPubSubType::serialize(
    const void* const data,
    eprosima::fastdds::rtps::SerializedPayload_t& payload,
    eprosima::fastdds::dds::DataRepresentationId_t repr
) {
    static_cast<void>(repr);
    if (data == nullptr) {
        return false;
    }

    const aisoc_raw_temp_t* sample = static_cast<const aisoc_raw_temp_t*>(data);
    char* buf_ptr = reinterpret_cast<char*>(payload.data);
    eprosima::fastcdr::FastBuffer fastbuffer(buf_ptr, payload.max_size);
    eprosima::fastcdr::Cdr ser(fastbuffer, eprosima::fastcdr::Cdr::DEFAULT_ENDIAN, eprosima::fastcdr::CdrVersion::XCDRv1);

    const bool is_big = (ser.endianness() == eprosima::fastcdr::Cdr::BIG_ENDIANNESS);
    payload.encapsulation = is_big ? CDR_BE : CDR_LE;
    ser.serialize_encapsulation();

    ser << sample->source_node;
    ser << sample->temperature_millic;
    ser << sample->sensor_status;
    ser << sample->raw_adc;
    ser << sample->sample_tick_ms;
    ser << sample->host_received_ns;
    ser << sample->sequence_id;

    payload.length = static_cast<uint32_t>(ser.get_serialized_data_length());
    return true;
}

bool RawTempPubSubType::deserialize(
    eprosima::fastdds::rtps::SerializedPayload_t& payload,
    void* data
) {
    if (data == nullptr) {
        return false;
    }

    aisoc_raw_temp_t* sample = static_cast<aisoc_raw_temp_t*>(data);
    char* buf_ptr = reinterpret_cast<char*>(payload.data);
    eprosima::fastcdr::FastBuffer fastbuffer(buf_ptr, payload.length);
    eprosima::fastcdr::Cdr deser(fastbuffer, eprosima::fastcdr::Cdr::DEFAULT_ENDIAN, eprosima::fastcdr::CdrVersion::XCDRv1);

    deser.read_encapsulation();
    deser >> sample->source_node;
    deser >> sample->temperature_millic;
    deser >> sample->sensor_status;
    deser >> sample->raw_adc;
    deser >> sample->sample_tick_ms;
    deser >> sample->host_received_ns;
    deser >> sample->sequence_id;

    return true;
}

uint32_t RawTempPubSubType::calculate_serialized_size(
    const void* const data,
    eprosima::fastdds::dds::DataRepresentationId_t repr
) {
    static_cast<void>(data);
    static_cast<void>(repr);
    return 40U;
}

